mapper.select:
SELECT p.id, p.tenant_id, p.biz_code, p.namespace_id, n.namespace_code, p.env_code, p.app_code,
       p.page_code, p.name, p.default_locale, p.version, p.published_version

ORDER BY p.page_code, p.id LIMIT #{limit} OFFSET #{offset}

SELECT b.id FROM ddc_namespace_env_app b
JOIN ddc_namespace n ON n.tenant_id = b.tenant_id AND n.id = b.namespace_id
JOIN ddc_app a ON a.tenant_id = b.tenant_id AND a.id = b.app_id
WHERE b.tenant_id = #{tenantId} AND n.biz_code = #{scope.bizCode}
AND n.namespace_code = #{scope.namespaceCode} AND b.env_code = #{scope.env}
AND a.biz_code = #{scope.bizCode} AND a.app_code = #{scope.appCode}
AND b.deleted_at IS NULL AND n.deleted_at IS NULL AND a.deleted_at IS NULL FOR SHARE OF b
